import argparse

def main(argv):
    parser = argparse.ArgumentParser(description="Recorded derived-label report; rate = WIN / (WIN + LOSS)")
    parser.add_argument("--input", required=True)
    args = parser.parse_args(argv)
    rows = load_rows(args.input)
    print(render_summary("overall", summarize(rows)))
    print("By source date (timezone unspecified):")
    days = by_day(rows)
    for name in sorted(days):
        print(render_summary(name, days[name]))
    print("By observed opponent card (groups overlap):")
    card_groups = by_card(rows)
    for name in sorted(card_groups):
        print(render_summary(name, card_groups[name]))
    return 0

